const section = (title, paragraphs, checkpoint, extras = {}) => ({ title, paragraphs, checkpoint, ...extras })
const recall = (question, example) => ({ question, example })

const modules = [
  {
    id: 'bsa-role-foundations', number: '01', title: 'Business Systems & Application Support Foundations', time: '75–90 min',
    summary: 'Understand how an analyst connects users, business processes, applications, vendors, data, and technical teams while keeping services dependable.',
    objectives: ['Explain what a business systems analyst owns', 'Separate symptoms, causes, requirements, and solutions', 'Use a safe end-to-end support workflow'],
    sections: [
      section('What the role actually does', ['A Business Systems & Applications Analyst keeps important applications useful, reliable, supportable, and aligned with business operations. The analyst is not only a senior help desk technician and not only a project business analyst. The role spans production support, administration, requirements, testing, vendor coordination, workflow design, documentation, training, and continual improvement.', 'Think of the analyst as a translator and systems thinker. Users describe business impact, logs expose technical behavior, vendors understand their product, and internal teams own surrounding systems. The analyst creates a shared problem statement, protects service, coordinates the right people, and carries work through validation instead of merely forwarding a ticket.'], { question: 'What makes this role different from Tier 1 support?', answer: 'It handles escalated application issues and also improves the system: deeper diagnosis, vendor ownership, requirements, testing, configuration, documentation, automation, and trend analysis.' }, { terms: [['Business system', 'Technology, data, people, and processes that enable a business capability.'], ['SaaS', 'Software operated by a provider and consumed as an online service.'], ['Stakeholder', 'A person or group affected by or able to influence the work.']] }),
      section('Products, services, processes, and workflows', ['An application is software; a business service is the useful capability people receive; a business process is the broader sequence that creates an outcome; and a workflow is a defined path of tasks, decisions, data, and handoffs. These terms overlap, but they are not interchangeable.', 'A purchasing application may be healthy while purchasing is blocked because an approval rule, integration, permission, supplier connection, or data condition is wrong. Strong analysts investigate the end-to-end service instead of stopping when the application screen loads.'], { question: 'The application is online, but invoices cannot complete approval. Is the business service healthy?', answer: 'No. Technical availability is only one condition. The end-to-end business outcome is unavailable, so workflow, data, identity, integration, configuration, and dependencies must be investigated.' }),
      section('A repeatable support lifecycle', ['Use a consistent sequence: acknowledge, clarify expected and actual behavior, assess impact and urgency, determine scope, preserve evidence, identify changes, form hypotheses, test safely, restore or work around, validate with the user, document, and follow up. Each step prevents common errors such as solving the wrong problem or closing on an unverified assumption.', 'Distinguish restoration from root cause. A workaround may return users to work while a vendor investigates a defect. Record the residual risk, owner, expiration, and long-term action so the temporary path does not quietly become permanent.'], { question: 'Why document a workaround’s owner and expiration?', answer: 'A workaround carries residual risk. Ownership and review prevent it from becoming an undocumented permanent solution while root cause or a durable fix is forgotten.' }, { steps: ['Define expected versus actual behavior.', 'Measure scope and business impact.', 'Preserve evidence and recent-change history.', 'Test one hypothesis at a time.', 'Restore service or establish an approved workaround.', 'Validate, document, communicate, and prevent recurrence.'] }),
      section('Safety, access, and change discipline', ['Administrative access can alter business records, permissions, integrations, or automated actions at large scale. Verify identity and authorization, use least privilege, separate test and production, preserve an audit trail, and understand rollback before changing settings. Helpful intent does not replace approval.', 'Never reproduce a destructive issue using real production data when a safe test is possible. Mask sensitive information in vendor cases, logs, screenshots, and test files. If diagnosis requires vendor access, define scope, duration, monitoring, and removal according to policy.'], { question: 'A vendor asks for a production database export to reproduce an issue. What should you do?', answer: 'Do not send it automatically. Confirm authorization and contract terms, minimize and mask data, use an approved secure transfer method, document access and retention, and prefer a safe test dataset when possible.' })
    ],
    command: 'Write a one-sentence support statement: user + expected outcome + actual behavior + scope + business impact + time.', commandNote: 'A precise problem statement aligns the user, analyst, technical teams, and vendor before anyone changes the system.',
    interviewQuestions: [recall('How do you approach an escalated application issue?', 'I confirm expected versus actual behavior, impact and scope; preserve evidence and changes; map dependencies; test the smallest useful hypothesis; restore or create an approved workaround; validate with users; document and pursue root cause.'), recall('How do you balance technical and business priorities?', 'I translate technical symptoms into affected business outcomes, time sensitivity, risk, and number of users, then use the agreed priority and escalation model.'), recall('When should an analyst avoid making an application change?', 'When authorization, data impact, security, dependencies, rollback, testing, or production risk is unclear. I pause, gather the missing facts, and use the change process.')]
  },
  {
    id: 'bsa-troubleshooting', number: '02', title: 'Advanced Application Troubleshooting', time: '90–105 min',
    summary: 'Turn vague application symptoms into evidence-based hypotheses across browser, identity, network, data, integration, configuration, and vendor layers.',
    objectives: ['Define scope with controlled comparisons', 'Collect useful client and server evidence', 'Isolate the failing layer without random changes'],
    sections: [
      section('Scope before cause', ['Ask whether the problem affects one user, role, device, browser, location, record, transaction type, integration, or everyone. Determine when it last worked and what changed. Controlled comparisons are powerful: same user on another device, another user with the same role, a known-good record, or the same operation in test.', 'Scope is evidence, not just a priority input. If one user fails everywhere, identity, license, role, profile, or data becomes more likely. If every user fails for one transaction type, shared configuration, workflow, integration, or data rules deserve attention.'], { question: 'One user fails on two devices while another user succeeds on both. What fault domain becomes more likely?', answer: 'The affected user’s identity, license, role, permissions, profile, or user-specific data rather than the devices themselves.' }),
      section('Follow the application request', ['A typical SaaS request travels from browser or client through DNS, network and proxy, identity provider, application front end, APIs, databases, integrations, and external services. Identify the last successful boundary. A login page proves some reachability but does not prove authorization or downstream services.', 'Use browser developer tools, correlation IDs, timestamps, HTTP status codes, application logs, identity sign-in logs, integration histories, job queues, and vendor status pages. Capture evidence in the organization’s approved systems and remove secrets or unnecessary personal information.'], { question: 'Why is an exact timestamp and correlation ID valuable?', answer: 'They let internal teams and vendors connect the user-visible failure to the correct request and log events across distributed components.' }, { terms: [['HTTP status code', 'A response category such as success, client error, or server error.'], ['Correlation ID', 'An identifier used to follow one request across systems and logs.'], ['Dependency', 'A service or component another service needs to complete its work.']] }),
      section('Hypotheses and controlled tests', ['A hypothesis should explain the observations and predict a test result. “The application is broken” is not useful. “The user lacks the new approval role because peers with that role succeed” is testable. Choose a read-only or reversible test that separates likely causes, then record the result.', 'Avoid changing several variables, clearing every cache, or granting broad permissions simultaneously. Those actions destroy diagnostic value and may introduce risk. If a reset is appropriate, first record the prior state and explain what the reset is intended to prove.'], { question: 'What makes a troubleshooting test useful?', answer: 'It is safe, tied to a specific hypothesis, predicts different results for competing causes, changes one variable when practical, and records evidence.' }, { steps: ['List confirmed observations.', 'Map likely layers and dependencies.', 'Create two or three explanations.', 'Choose the safest differentiating test.', 'Record the result and update the hypothesis.', 'Restore, validate, and document.'] }),
      section('Intermittent and data-specific failures', ['Intermittent faults require timelines and patterns: user, record, volume, time, browser, node, region, release, load, or integration batch. Do not conclude that “it works now” means the issue is resolved. Preserve failed examples and compare them with successful ones.', 'Data-specific failures often involve required fields, formats, duplicate keys, invalid states, permissions, reference data, character encoding, file size, or business rules. Use copies or masked test records, protect chain of custody for important business data, and never alter production records merely to see what happens.'], { question: 'How should you investigate a failure that occurs only for certain records?', answer: 'Compare failed and successful records across schema, state, permissions, reference data, size, encoding, and business rules using approved masked copies or read-only evidence.' })
    ],
    command: 'Create an evidence table with columns: timestamp, user/role, record, action, expected, actual, correlation ID, environment, recent change.', commandNote: 'Patterns become visible when observations share a consistent structure.',
    interviewQuestions: [recall('How do you troubleshoot a SaaS issue you cannot reproduce?', 'I collect exact steps, timestamps, identifiers, scope, failed examples, environment, logs, and change history; compare successful cases; monitor for recurrence; and give the vendor a bounded evidence package.'), recall('How do you prevent troubleshooting from making the incident worse?', 'I favor read-only evidence, test outside production, change one variable, preserve prior state, use least privilege, define rollback, and communicate before impactful actions.'), recall('What do you include in advanced application ticket notes?', 'Expected and actual behavior, business impact, scope, timestamps, identifiers, evidence, hypotheses, tests and results, changes, workaround, validation, owners, and next update.')]
  },
  {
    id: 'bsa-tickets-slas', number: '03', title: 'Ticket Operations, SLAs & Communication', time: '75–90 min',
    summary: 'Prioritize incoming work fairly, protect service targets, communicate under uncertainty, and create handoffs that do not lose context.',
    objectives: ['Prioritize by impact and urgency', 'Distinguish SLA measures and operational targets', 'Write clear updates and escalations'],
    sections: [
      section('Impact, urgency, and priority', ['Impact describes the breadth or severity of business effect. Urgency describes how quickly harm grows. Priority combines these factors using an agreed matrix, with safety, legal, financial, deadline, and executive escalation rules where documented. The loudest requester is not automatically the highest priority.', 'Reassess priority when scope changes. One user with a workaround can become a major incident if the same defect spreads to all locations. Record why the priority was selected so decisions remain explainable.'], { question: 'What is the difference between impact and urgency?', answer: 'Impact is how broadly or severely the business is affected; urgency is how quickly consequences increase or resolution is needed.' }),
      section('What an SLA means', ['A service level agreement defines agreed service expectations such as availability, support hours, initial response, update cadence, or resolution targets. A response target is not a resolution promise. Internal operational agreements and vendor contracts may support the customer-facing commitment.', 'Track the correct clock rules, pauses, priority changes, and ownership. Do not game an SLA by closing unresolved work. If a target is at risk, communicate early, escalate with evidence, document dependencies, and propose a workaround or recovery plan.'], { question: 'Why is “responded within 30 minutes” different from “resolved within 30 minutes”?', answer: 'Response confirms acknowledgement and ownership; resolution restores the agreed outcome. They measure different stages and should not be reported as the same achievement.' }, { terms: [['SLA', 'An agreement defining measurable service expectations.'], ['OLA', 'An internal agreement supporting delivery of an SLA.'], ['Escalation', 'Bringing additional expertise, authority, or attention to work.']] }),
      section('Updates during uncertainty', ['A useful update says what is confirmed, business impact, current owner, actions completed, safe workaround, current risk, next action, and next update time. Separate facts from hypotheses. Avoid silence, false certainty, and streams of unexplained technical detail.', 'Tailor communication. End users need the effect and what to do. Leaders need scope, risk, options, and decisions. Engineers and vendors need reproducible evidence. Everyone should see consistent facts even when the level of detail differs.'], { question: 'What should you say when root cause is still unknown?', answer: 'State confirmed facts and scope, explain what is being checked, provide any safe workaround, identify ownership and risk, and commit to a specific next update without guessing.' }),
      section('Escalation and major-incident behavior', ['Escalate for missing expertise, authority, access, time, vendor action, security risk, or growing business impact. A good escalation is a prepared handoff containing problem statement, timeline, evidence, actions and results, current state, workaround, risk, and an explicit request.', 'For widespread impact, establish one incident owner, an action log, communication channel, technical workstream, stakeholder update rhythm, and decision authority. Parallel work should be coordinated so teams do not make conflicting changes or ask users the same questions repeatedly.'], { question: 'What makes an escalation actionable?', answer: 'It includes a concise problem, impact, timeline, evidence, tests and results, current state and risk, plus the exact help or decision required.' })
    ],
    command: 'Draft a 60-word incident update: impact → confirmed facts → workaround → next action → owner → next update.', commandNote: 'Short, predictable updates reduce anxiety and let stakeholders make decisions without reading the entire ticket.',
    interviewQuestions: [recall('How do you prioritize multiple application tickets?', 'I use the documented impact-and-urgency matrix, consider safety and deadlines, confirm SLA clocks, communicate ownership, delegate where possible, and re-prioritize as scope changes.'), recall('How do you handle an SLA at risk?', 'I verify the target and clock, escalate early, document dependencies, communicate impact and next steps, pursue a safe workaround, and keep ownership through resolution.'), recall('How do you communicate a major incident?', 'I establish a single source of truth and update cadence, state scope and impact, separate facts from hypotheses, track actions and decisions, and tailor detail to each audience.')]
  },
  {
    id: 'bsa-vendors', number: '04', title: 'Vendor Management & Root Cause Analysis', time: '75–90 min',
    summary: 'Build effective vendor cases, manage ownership across company boundaries, escalate intelligently, and turn repeated defects into corrective action.',
    objectives: ['Create a vendor-ready evidence package', 'Manage severity and escalation without losing internal ownership', 'Facilitate blameless root cause analysis'],
    sections: [
      section('Build a case the vendor can act on', ['Include tenant or instance, environment, version, business impact, scope, start time and timezone, exact reproduction steps, expected and actual results, correlation IDs, sanitized logs, screenshots, frequency, change history, and workarounds. State what you already tested and the result.', 'Do not bury the request. Ask for a specific action: confirm a known issue, analyze a trace, provide a mitigation, clarify product behavior, supply a hotfix, or escalate to engineering. Follow the approved data-sharing and support-access process.'], { question: 'Why should a vendor case contain both expected and actual behavior?', answer: 'It defines the failure precisely and prevents disagreement about whether the observed behavior is a defect, configuration issue, or misunderstood requirement.' }),
      section('Severity, entitlement, and escalation', ['Vendor severity definitions may depend on production impact, number of users, workaround availability, and service criticality. Match the contract rather than inflating severity. Know support hours, response targets, escalation paths, maintenance policies, service credits, and account contacts.', 'When progress stalls, summarize the current evidence, missed commitments, business risk, and required next action. Escalate through the documented channel while maintaining a professional record. The vendor owns its product investigation; your organization still owns stakeholder impact and internal coordination.'], { question: 'Why is exaggerating vendor severity harmful?', answer: 'It can violate support terms, damage credibility, divert resources, and make future legitimate escalations less effective.' }),
      section('Root cause versus contributing conditions', ['A root cause analysis explains the technical and organizational conditions that allowed an incident and identifies controls that reduce recurrence. Avoid stopping at “human error.” Ask why the action was possible, why detection failed, why recovery took time, and which safeguards were missing.', 'Build a timeline from evidence. Separate trigger, root cause, contributing factors, detection gaps, response factors, and business impact. Corrective actions need an owner, due date, priority, measurable completion, and validation—not just a meeting note.'], { question: 'Why is “an administrator made a mistake” usually an incomplete root cause?', answer: 'It does not explain why the system allowed the error, why safeguards or review did not prevent it, why monitoring did not detect it, or how recurrence will be reduced.' }, { terms: [['Root cause', 'A fundamental condition whose control reduces recurrence.'], ['Contributing factor', 'A condition that increased likelihood, impact, or recovery time.'], ['Corrective action', 'Owned work intended to remove or control a cause.']] }),
      section('Recurring defects and vendor leverage', ['Track affected releases, tenants, features, counts, downtime, workarounds, support cases, and business cost. Patterns make escalation stronger than isolated anecdotes. Link related incidents to a problem record and request a durable vendor response such as defect ID, target release, mitigation, or architectural guidance.', 'Review release notes and known issues against your environment. After a vendor fix, reproduce the original failure in test, run regression tests, monitor production, and close only after the business outcome remains stable.'], { question: 'What evidence strengthens escalation for a recurring vendor defect?', answer: 'Linked cases, frequency, affected versions and workflows, business impact, consistent reproduction, workarounds and costs, defect identifiers, and validation that the pattern is the same.' })
    ],
    command: 'Create a vendor case header: severity | business impact | start time/timezone | scope | environment | correlation IDs | requested action.', commandNote: 'The first screen should tell vendor support why the case matters and what they need to do next.',
    interviewQuestions: [recall('What do you send to a SaaS vendor for a complex defect?', 'A sanitized, reproducible evidence package with environment, impact, scope, timestamps, correlation IDs, expected and actual behavior, logs, changes, tests, workaround, and a specific requested action.'), recall('How do you handle a vendor who is not progressing a critical case?', 'I restate evidence and impact, confirm contractual severity and commitments, request the next technical action and update time, escalate through account channels, and continue internal workaround and communication ownership.'), recall('How do you run root cause analysis without blame?', 'I use an evidence-based timeline and examine technical cause, system conditions, controls, detection, response, and recovery, then assign measurable corrective actions with owners and validation.')]
  },
  {
    id: 'bsa-requirements', number: '05', title: 'Business Analysis & Requirements', time: '90–105 min',
    summary: 'Discover the real business need, map current and future workflows, write testable requirements, and recommend proportionate solutions.',
    objectives: ['Separate needs from requested solutions', 'Gather and validate functional and nonfunctional requirements', 'Manage scope, assumptions, and traceability'],
    sections: [
      section('Start with the problem and outcome', ['Stakeholders often request a feature: “Add another approval button.” Ask what problem they are solving, who is affected, what outcome matters, how often it occurs, current cost or risk, and what constraints apply. The requested feature is one possible solution, not automatically the requirement.', 'Write a problem statement with current condition, affected stakeholders, consequence, desired outcome, and evidence. Define how success will be measured. This keeps the project from delivering exactly what was requested while missing the actual need.'], { question: 'Why should an analyst avoid recording the requested solution as the requirement?', answer: 'It can lock the team into one design before the underlying need, alternatives, constraints, and success measures are understood.' }),
      section('Elicitation techniques', ['Use interviews for depth, workshops for shared decisions, observation for real behavior, document and data analysis for evidence, surveys for breadth, prototypes for feedback, and process mapping for handoffs and exceptions. Select techniques based on risk, complexity, availability, and stakeholder diversity.', 'Ask open questions first, then clarify rules, data, volumes, exceptions, permissions, deadlines, integrations, reporting, accessibility, compliance, and support. Reflect the finding back and validate it with the people who perform and own the work.'], { question: 'When is observation especially valuable?', answer: 'When documented procedures differ from real work, important tacit steps or workarounds exist, or users struggle to describe a complex workflow.' }),
      section('Functional and nonfunctional requirements', ['Functional requirements describe what the system must do: validate an invoice, route an approval, produce a report, or synchronize a record. Nonfunctional requirements describe qualities and constraints such as performance, availability, security, accessibility, auditability, retention, recovery, usability, and supportability.', 'Make requirements specific, necessary, feasible, unambiguous, and testable. “The system must be fast” is weak. “For 95 percent of approved searches under normal load, results appear within three seconds” gives a measurable condition and context.'], { question: 'Is “Only payroll managers may approve an adjustment, and the action must be audited” functional or nonfunctional?', answer: 'It contains both: the approval capability is functional, while authorization and auditability are security and compliance qualities.' }, { terms: [['Acceptance criterion', 'A testable condition that must be satisfied for work to be accepted.'], ['Business rule', 'A policy or condition governing business behavior.'], ['Nonfunctional requirement', 'A required quality or constraint rather than a specific feature.']] }),
      section('Prioritization and traceability', ['Prioritize by value, risk, dependency, compliance, effort, urgency, and learning. MoSCoW labels—Must, Should, Could, and Won’t for this scope—can support discussion, but every item cannot be a Must. Record the decision owner and rationale.', 'A traceability matrix links business objective to requirement, design or configuration, test case, result, release, and documentation. It helps prove coverage and manage change. When a requirement changes, inspect affected tests, workflows, integrations, training, data, and support.'], { question: 'What does requirements traceability help an analyst answer?', answer: 'Why a requirement exists, how it is implemented, where it is tested, whether it passed, what release contains it, and what else changes if it changes.' })
    ],
    command: 'Rewrite “Make approvals easier” as: actor + trigger + behavior + rule + exception + measurable acceptance criteria.', commandNote: 'Good requirements make the need and test conditions clear without prescribing unnecessary implementation detail.',
    interviewQuestions: [recall('How do you gather requirements from stakeholders who disagree?', 'I establish the shared outcome, map current work with evidence, capture each need and constraint, identify decision authority, facilitate tradeoffs, document assumptions and open decisions, and validate the agreed future state.'), recall('How do you know a requirement is ready?', 'It is understood, valuable, feasible enough to proceed, uniquely identified, prioritized, testable, traced to an objective, and accepted by the appropriate owner.'), recall('Give an example of a nonfunctional requirement.', 'For example: 95 percent of normal searches must return within three seconds, with audit logs retained under the approved policy and access restricted by role.')]
  },
  {
    id: 'bsa-testing-releases', number: '06', title: 'Application Testing, Releases & Configuration', time: '90–105 min',
    summary: 'Turn requirements and incident risks into repeatable tests for vendor releases, upgrades, configuration changes, integrations, and production validation.',
    objectives: ['Design tests from risk and requirements', 'Coordinate UAT and regression testing', 'Manage releases with rollback and validation'],
    sections: [
      section('Test levels and purposes', ['Unit tests check small code units, integration tests check boundaries, system tests check the complete application, user acceptance testing confirms business fitness, regression testing checks that existing behavior still works, and smoke tests quickly verify critical operation after deployment. Analysts may not write every automated test, but they connect business risk to coverage.', 'A test case includes objective, requirement, prerequisites, data, steps, expected result, actual result, evidence, status, and defect reference. Include positive, negative, boundary, permission, data-volume, failure, accessibility, and recovery conditions according to risk.'], { question: 'What is the main purpose of user acceptance testing?', answer: 'To confirm with authorized business representatives that the solution supports required real-world outcomes and acceptance criteria.' }),
      section('Regression and risk-based coverage', ['A vendor release can affect integrations, permissions, reports, browser behavior, automation, exports, and data even when the highlighted feature is unrelated. Maintain a regression pack for critical business journeys and high-risk dependencies. Prioritize by business impact, likelihood, change surface, defect history, and recoverability.', 'Do not claim that testing proves the absence of defects. Testing provides evidence about known risks under tested conditions. Record environment and data differences that limit confidence.'], { question: 'How should an analyst choose regression tests when time is limited?', answer: 'Prioritize critical business journeys, changed and integrated areas, security and permissions, frequent use, prior defects, high impact, and functions that are difficult to recover.' }),
      section('Defects and release decisions', ['A useful defect contains a concise title, environment and build, prerequisites, steps, expected and actual results, frequency, scope, severity, evidence, and links to requirement and test. Severity describes technical or business effect; priority describes when it should be fixed.', 'A go/no-go decision considers passed and failed tests, open defects, workarounds, security, data integrity, operational readiness, training, monitoring, support, rollback, and accountable risk acceptance. The analyst presents evidence and options; the designated business and technical owners make the decision.'], { question: 'What is the difference between defect severity and priority?', answer: 'Severity describes impact of the defect; priority describes the order or urgency with which it should be addressed. They influence each other but are not identical.' }),
      section('Configuration and release control', ['Treat configuration as production code where possible: record current state, reason, owner, approval, dependencies, test evidence, implementation steps, rollback, validation, and documentation. Separate environments and use peer review for high-impact rules, permissions, integrations, and automation.', 'After release, perform smoke tests, inspect monitoring and queues, validate a business transaction, confirm integrations, communicate status, and schedule a follow-up review. Roll back based on pre-agreed thresholds rather than optimism.'], { question: 'What must be defined before a risky production configuration change?', answer: 'Scope, current state, authorization, dependencies, test evidence, implementation and communication plan, rollback criteria and steps, validation, monitoring, and ownership.' }, { steps: ['Review change and affected requirements.', 'Select risk-based regression and UAT coverage.', 'Prepare environment, data, owners, and schedule.', 'Record results and defects.', 'Make an evidence-based release decision.', 'Deploy, smoke-test, monitor, communicate, and review.'] })
    ],
    command: 'Write one test case: requirement ID | precondition | data | steps | expected result | evidence | pass/fail.', commandNote: 'If the expected result cannot be observed objectively, improve the acceptance criterion before testing.',
    interviewQuestions: [recall('How do you test a vendor release?', 'I review release notes and known issues, map affected workflows and integrations, run risk-based regression and UAT in a representative environment, track defects, confirm operational readiness and rollback, then smoke-test and monitor production.'), recall('What makes a good test case?', 'It traces to a requirement or risk and specifies prerequisites, controlled data, repeatable steps, an observable expected result, evidence, and status.'), recall('When would you recommend no-go?', 'When unresolved risk to critical outcomes, security, data integrity, recovery, compliance, or support exceeds authorized tolerance and no acceptable workaround or rollback exists.')]
  },
  {
    id: 'bsa-automation', number: '07', title: 'Workflow Design & Automation', time: '90–105 min',
    summary: 'Map work before automating it, design maintainable flows, protect credentials and data, handle failure, and measure whether automation creates value.',
    objectives: ['Identify suitable automation opportunities', 'Design triggers, actions, decisions, exceptions, and controls', 'Operate Power Automate-style workflows safely'],
    sections: [
      section('Improve before you automate', ['Map the current workflow: trigger, actors, inputs, decisions, business rules, handoffs, waits, rework, exceptions, outputs, systems, and measures. Remove unnecessary steps and clarify ownership before automation. Automating a confused process makes confusion faster and harder to see.', 'Good candidates are stable, repeatable, rule-based, sufficiently frequent, and supported by reliable data and APIs. Poor candidates depend on unresolved policy, subjective judgment without guardrails, constantly changing exceptions, or access that cannot be controlled safely.'], { question: 'Why should a process be simplified before automation?', answer: 'Automation scales the current behavior. Simplifying first avoids encoding waste, unclear rules, duplicate work, and unsafe exceptions.' }),
      section('Flow anatomy and reliability', ['A workflow has a trigger, data inputs, conditions, actions, loops, connections, outputs, and error paths. Design for retries, timeouts, duplicate events, partial completion, concurrency, rate limits, and unavailable dependencies. Idempotency means a repeated operation produces the intended state without harmful duplication.', 'Use meaningful names, small scopes, comments for business intent, reusable child flows when appropriate, explicit ownership, environment configuration, and versioned deployment. Do not build a critical flow that only one employee can access or understand.'], { question: 'What problem does idempotency solve?', answer: 'It allows a retried or duplicate request to reach the intended state without creating duplicate records, payments, messages, or other harmful repeated effects.' }, { terms: [['Trigger', 'The event or schedule that starts an automation.'], ['Connector', 'An integration interface used by an automation platform.'], ['Idempotent', 'Safe to repeat without unintended additional effect.']] }),
      section('Security and governance', ['Use service identities or approved connection references, least privilege, environment separation, data loss prevention policies, secret management, audit logs, retention, and change control. Personal credentials create continuity risk and may give flows more access than intended.', 'Validate and minimize input. Treat email, uploaded files, and external data as untrusted. Require human approval for high-impact actions such as payments, access changes, deletion, or external publication when policy demands it. Never put passwords or secrets in flow names, comments, notifications, or plain configuration.'], { question: 'Why are personal user connections risky for business-critical flows?', answer: 'The flow may fail or retain inappropriate access when the employee changes roles, leaves, resets credentials, or loses a license; ownership and privileges are also harder to govern.' }),
      section('Monitoring, support, and value', ['Define success, failure, duration, queue, retry, and business-outcome measures. Send actionable alerts with flow, run, timestamp, affected record, error category, and support link—without exposing secrets. Create a support playbook and known-safe replay or recovery method.', 'Measure time saved, error reduction, cycle time, experience, compliance, and exceptions, not just run count. Review unused or failing flows, ownership, connections, permissions, and licenses. Retire automation cleanly when the process or application changes.'], { question: 'What should an automation alert contain?', answer: 'The affected workflow and run, time, record or scope, sanitized error category, current state, owner, and a link to the support procedure or evidence.' }, { steps: ['Map and simplify the process.', 'Define rules, exceptions, data, and ownership.', 'Design secure triggers, actions, and failure paths.', 'Build and test in a separate environment.', 'Deploy through controlled lifecycle management.', 'Monitor business value, reliability, access, and ownership.'] })
    ],
    command: 'Design a flow on paper: trigger → validate → decision → action → exception → notify → audit → measure.', commandNote: 'Include what happens when a dependency times out or the same event arrives twice.',
    interviewQuestions: [recall('How do you choose a process to automate?', 'I look for a stable, repetitive, rule-based process with reliable data and clear ownership, then compare value, volume, risk, exceptions, integration capability, maintenance, and alternatives.'), recall('How do you make an automation supportable?', 'I use approved identities and environments, least privilege, meaningful structure, error handling, idempotency, logging, alerts, documentation, shared ownership, tests, deployment control, and a recovery playbook.'), recall('How do you measure automation success?', 'I compare the baseline with cycle time, manual effort, errors, exceptions, experience, compliance, reliability, and total operating cost—not just the number of runs.')]
  },
  {
    id: 'bsa-sharepoint-migration', number: '08', title: 'SharePoint Information Architecture & Large File Migrations', time: '105–120 min',
    summary: 'Plan, assess, pilot, migrate, validate, and support large file-share moves into SharePoint without treating migration as a blind copy operation.',
    objectives: ['Choose appropriate SharePoint destinations and structure', 'Plan permissions, metadata, volume, performance, and cutover', 'Validate content and user outcomes after migration'],
    sections: [
      section('Start with purpose and information architecture', ['SharePoint is not simply a network drive in a browser. Decide which content belongs in team sites, communication sites, document libraries, Teams-connected sites, or individual OneDrive based on ownership, collaboration, lifecycle, audience, and governance. Design sites, libraries, metadata, views, content types, search, retention, and navigation around how people find and manage information.', 'Inventory the source and identify owners. Remove redundant, obsolete, and trivial content under approved retention rules. Capture volumes, file counts, sizes, ages, extensions, path lengths, permissions, sensitivity, links, duplicates, locked files, and applications that depend on paths. Never delete source content merely because a scan labels it old.'], { question: 'Why is copying an entire file share into one SharePoint library usually weak design?', answer: 'It preserves outdated structure without addressing ownership, collaboration, metadata, search, permissions, retention, path dependencies, or how users should work in the destination.' }),
      section('Permissions, sharing, and governance', ['File-share permissions do not always map cleanly to SharePoint groups, inheritance, sharing links, site ownership, or Microsoft 365 groups. Design least-privilege destination groups, minimize unique item permissions, identify external sharing, and have owners approve mappings. Test with representative non-admin users.', 'Define ownership, classification, retention, records, sensitivity labels, versioning, recycle behavior, external sharing, naming, provisioning, and lifecycle before cutover. A technically successful migration can still create a governance or privacy failure.'], { question: 'Why should migration validation include non-administrator test users?', answer: 'Administrators can access content that normal users cannot, masking missing permissions, excessive access, navigation problems, and real user experience.' }),
      section('Assess, pilot, and schedule', ['Microsoft migration tooling follows planning, assessment and remediation, destination preparation, migration, monitoring, and user onboarding. Scans identify unsupported or risky items before data moves. The SharePoint Migration Tool processes scanning, packaging, upload, and import; Migration Manager can coordinate file-share tasks and agents.', 'Pilot a representative set containing large files, many small files, deep paths, special characters, permissions, versions where relevant, sensitive data, and business-critical workflows. Measure throughput and error patterns. Performance depends on source read speed, migration-computer disk, network connectivity, file distribution, scheduling, and service throttling; more parallel work helps only until a shared bottleneck is reached.'], { question: 'Why should a migration pilot include both large files and many small files?', answer: 'They stress different bottlenecks and processing overhead, so one type alone does not predict production throughput or error behavior.' }, { terms: [['SPMT', 'Microsoft SharePoint Migration Tool.'], ['Migration Manager', 'Microsoft 365 capability for centrally coordinating supported migrations.'], ['Throttling', 'Service protection that temporarily limits request rate or throughput.']] }),
      section('Incremental migration, cutover, and validation', ['A common approach performs an initial bulk migration, remediates exceptions, runs incremental passes, freezes or controls source changes during cutover, completes a final delta, validates, then directs users to the destination. Define rollback or source-read-only contingencies, support coverage, communications, and decision authority.', 'Validate counts, sizes, samples, checksums when available, permissions, metadata, versions when in scope, dates, search, sharing, links, automations, integrations, and user workflows. Reconcile every failure report to an owner and outcome. Keep source data according to approved rollback and retention plans rather than deleting immediately.'], { question: 'What must be validated besides file count?', answer: 'File size and content samples, permissions, metadata, versions in scope, dates, search, sharing, links, automation, integrations, failed items, and actual user workflows.' }, { steps: ['Discover content, dependencies, owners, volume, and risk.', 'Design destination information architecture and governance.', 'Assess and remediate unsupported or unwanted content.', 'Pilot representative data and measure throughput.', 'Run bulk and incremental migrations with monitoring.', 'Cut over, validate, onboard users, resolve exceptions, and retire source under approval.'] })
    ],
    command: 'Build a migration inventory: source | owner | destination | files | bytes | permissions | sensitivity | dependencies | disposition | validation owner.', commandNote: 'A reliable migration is an information, access, workflow, and adoption project—not only a transfer job.',
    interviewQuestions: [recall('How would you plan a large file migration into SharePoint?', 'I inventory and classify content, confirm owners and retention, design destinations and permission groups, assess and remediate, pilot representative data, baseline throughput, run bulk and incremental passes, control cutover, validate content and workflows, onboard users, and reconcile exceptions.'), recall('What can limit SharePoint migration throughput?', 'Source storage and network speed, migration-host disk and CPU, internet connectivity, file count and size distribution, concurrency, scheduling, and Microsoft 365 throttling.'), recall('How do you validate a migration?', 'I reconcile counts and sizes, sample or hash content, test permissions as normal users, verify metadata, versions in scope, search, sharing, links, automations and integrations, and obtain business-owner acceptance.')]
  },
  {
    id: 'bsa-documentation-improvement', number: '09', title: 'Documentation, Knowledge Transfer & Continual Improvement', time: '75–90 min',
    summary: 'Create documentation people can trust, enable Tier 1 and users, analyze support trends, and turn recurring work into measurable system improvements.',
    objectives: ['Create operational and user documentation', 'Deliver useful knowledge transfer', 'Analyze trends and maintain an improvement backlog'],
    sections: [
      section('A useful system knowledge base', ['Maintain a service overview, owners, users, business processes, environments, architecture and integrations, data classification, authentication, roles, administrative procedures, configuration, monitoring, SLAs, vendor contacts, maintenance, known issues, recovery, release history, and document review dates. Separate sensitive administrative details from broad user guidance.', 'Every article needs an audience, purpose, prerequisites, safe steps, expected result, validation, escalation path, owner, and last-reviewed date. Screenshots can help but become stale; pair them with labels and outcomes that survive minor interface changes.'], { question: 'What makes a knowledge article trustworthy over time?', answer: 'Clear ownership, scope and audience, tested steps, expected results, escalation guidance, change linkage, feedback, and a visible review date.' }),
      section('Known errors, workarounds, and runbooks', ['A known-issue record captures symptom, scope, cause if known, identifiers, safe workaround, limitations, risks, affected versions, vendor case, owner, and resolution status. Link it from tickets so Tier 1 can act consistently without concealing recurrence.', 'A runbook describes an operational response with triggers, authority, prerequisites, decision points, commands or actions, validation, rollback, communication, and escalation. Test runbooks through exercises; documentation that has never been executed is only a hypothesis.'], { question: 'What is the risk of documenting a workaround without its limitations?', answer: 'Technicians may use it in unsafe or inappropriate situations, treat temporary restoration as resolution, and hide recurring impact.' }),
      section('Training and knowledge transfer', ['Start with what the learner must do, not every feature the application offers. Use realistic tasks, demonstrations, guided practice, independent practice, job aids, knowledge checks, and a support path. Adjust language for Tier 1, administrators, power users, and general users.', 'For Tier 1, define symptoms they can handle, evidence to collect, safe actions, stop conditions, and escalation requirements. Measure whether transfer reduces avoidable escalations while maintaining quality—ticket deflection alone can hide frustrated users.'], { question: 'What should a Tier 1 troubleshooting guide include?', answer: 'Recognizable scope, questions and evidence, authorized safe steps, expected results, stop conditions, escalation criteria, and the information required for handoff.' }),
      section('Trend analysis and improvement', ['Categorize tickets consistently by application, feature, symptom, cause, resolution, location, user group, release, vendor, and recurrence. Examine rate as well as count because user population or transaction volume may change. Review repeat contacts, reopen rate, backlog age, SLA risk, resolution time, defect recurrence, workaround use, and experience.', 'Validate patterns with samples instead of trusting inconsistent categories. Build an improvement backlog with problem statement, evidence, affected outcome, proposed option, value, effort, risk, dependencies, owner, and measure. After implementation, compare with baseline and check for unintended effects.'], { question: 'Why can raw ticket count be misleading?', answer: 'The number of users or transactions may have changed, duplicates may exist, categorization may be inconsistent, and one severe recurring defect can matter more than many simple requests.' }, { steps: ['Normalize and validate support data.', 'Identify repeated symptoms and high-cost journeys.', 'Investigate cause and affected business outcome.', 'Prioritize by value, risk, effort, and dependency.', 'Implement in controlled increments.', 'Measure results and update knowledge.'] })
    ],
    command: 'Turn five related tickets into one problem statement with baseline, likely cause, affected outcome, proposed improvement, owner, and measure.', commandNote: 'Trend work becomes useful when it produces an owned, testable improvement rather than another dashboard.',
    interviewQuestions: [recall('How do you keep application documentation current?', 'I assign owners and review dates, link updates to changes and incidents, test procedures, collect reader feedback, monitor failed searches and escalations, and archive superseded content.'), recall('How do you transfer knowledge to Tier 1?', 'I define their authorized scope, teach symptom recognition and evidence collection, provide tested decision guides with stop conditions, practice realistic cases, and review escalation quality and outcomes.'), recall('How do you identify application improvements from tickets?', 'I normalize and sample the data, examine frequency, rate, impact, recurrence, effort and affected workflows, validate with users and system evidence, prioritize an owned backlog, and measure after change.')]
  }
]

const quizQuestions = [
  { q: 'What best distinguishes a business system from an application?', choices: ['A business system includes people, process, data, technology, and controls that enable an outcome', 'A business system is only an application hosted internally', 'A business system is any vendor contract', 'There is no meaningful distinction'], answer: 0, why: 'The application is one component; the business system includes the complete capability and operating context.' },
  { q: 'The SaaS login page loads, but approvals fail. What is the best conclusion?', choices: ['Some front-end reachability works, but authorization, workflow, data, APIs, or dependencies may still fail', 'The entire service is proven healthy', 'DNS must be the root cause', 'The user device must be replaced'], answer: 0, why: 'One successful boundary narrows the problem but does not validate the end-to-end transaction.' },
  { q: 'Which problem statement is strongest?', choices: ['Since 09:10 CT, 24 invoice approvers receive error 403 after selecting Approve; submissions remain pending and payroll cutoff is 14:00', 'The app is broken again', 'Users are unhappy with the system', 'Please fix approvals urgently'], answer: 0, why: 'It defines time, scope, action, evidence, state, and business urgency.' },
  { q: 'When is a workaround appropriately considered successful?', choices: ['It restores an acceptable outcome, is validated, documented with risk and ownership, and does not hide long-term action', 'It makes the error disappear once', 'It permanently replaces root cause analysis', 'It requires unrestricted administrator access'], answer: 0, why: 'A workaround is controlled temporary restoration with residual risk and follow-up.' },
  { q: 'One user fails on every device while peers with the same workflow succeed. What should be compared first?', choices: ['Identity, license, role, permissions, profile, and user-specific data', 'Building power', 'Every vendor data center', 'All workstation hardware'], answer: 0, why: 'The comparison makes a user-specific domain more likely.' },
  { q: 'Why capture a correlation ID?', choices: ['To connect one user transaction with related records across distributed logs', 'To replace the incident ticket number', 'To grant temporary access', 'To prove the vendor caused the issue'], answer: 0, why: 'Correlation identifiers help trace the same request across components.' },
  { q: 'Which troubleshooting action gives the strongest diagnostic value?', choices: ['Test one safe hypothesis with a predicted result and record the observation', 'Clear every cache and reset every permission simultaneously', 'Restart production repeatedly until it works', 'Grant administrator rights to eliminate security questions'], answer: 0, why: 'Controlled differentiating tests preserve causality and reduce risk.' },
  { q: 'A failure affects only records containing a new reference code. What should be investigated?', choices: ['Validation rules, reference data, schema, encoding, workflow state, and integrations for that code', 'Laptop batteries', 'Office Wi-Fi channels only', 'Every unrelated application'], answer: 0, why: 'The data pattern points toward record-specific rules and dependencies.' },
  { q: 'What determines ticket priority most fairly?', choices: ['Documented impact and urgency, including approved safety and business rules', 'Requester seniority alone', 'The order in which users complain', 'The longest ticket description'], answer: 0, why: 'Priority should be repeatable and tied to business effect and time sensitivity.' },
  { q: 'What does an SLA response target measure?', choices: ['How quickly ownership and acknowledgement occur under the agreement', 'Guaranteed permanent resolution time in every case', 'The number of vendor engineers assigned', 'Only application availability'], answer: 0, why: 'Response and resolution are distinct service measures.' },
  { q: 'What is the best update when root cause is unknown?', choices: ['Confirmed scope and impact, completed actions, current owner, workaround, next step, risk, and next update time', 'No update until the issue is resolved', 'A confident guess to reassure users', 'All raw logs without explanation'], answer: 0, why: 'An honest, structured update supports decisions without inventing certainty.' },
  { q: 'What should an escalation request make explicit?', choices: ['The exact expertise, access, action, or decision needed from the receiving party', 'Only that the ticket is urgent', 'That the original analyst is no longer involved', 'Every ticket handled that month'], answer: 0, why: 'A prepared handoff asks for a specific next contribution while preserving ownership.' },
  { q: 'Which evidence package is most useful to a SaaS vendor?', choices: ['Sanitized reproduction, environment, scope, impact, times, IDs, logs, changes, tests, workaround, and requested action', 'A screenshot saying error', 'The user password', 'A full production database sent without approval'], answer: 0, why: 'The package lets the vendor reproduce, trace, prioritize, and act safely.' },
  { q: 'Why should vendor severity match contract definitions?', choices: ['It preserves credibility and routes the case according to agreed impact and response rules', 'It prevents internal communication', 'It guarantees a defect fix', 'It removes the need for evidence'], answer: 0, why: 'Accurate severity makes escalation defensible and effective.' },
  { q: 'Why is “human error” an incomplete root cause?', choices: ['It does not explain system conditions, controls, detection, or why the action produced the impact', 'People never make mistakes', 'Only vendors can create root causes', 'Root cause analysis excludes process'], answer: 0, why: 'Useful RCA identifies controllable conditions rather than stopping at blame.' },
  { q: 'What turns an RCA recommendation into a corrective action?', choices: ['Clear scope, owner, due date, priority, measurable completion, and validation', 'Adding it to meeting notes', 'Calling it best practice', 'Waiting for another incident'], answer: 0, why: 'Corrective action must be owned, completed, and shown to reduce risk.' },
  { q: 'A stakeholder says “Add another approval button.” What should the analyst ask first?', choices: ['What business problem, users, outcome, evidence, rules, and constraints are behind the request?', 'What color should it be?', 'Which developer can start immediately?', 'How can the request avoid testing?'], answer: 0, why: 'The feature request may not be the best solution to the underlying need.' },
  { q: 'When is direct observation especially useful for requirements?', choices: ['When real work contains tacit steps, exceptions, or workarounds missing from documentation', 'When no users perform the process', 'When the solution is already deployed', 'Only for hardware requirements'], answer: 0, why: 'Observation reveals behavior people may not remember or articulate.' },
  { q: 'Which is a testable nonfunctional requirement?', choices: ['Under normal load, 95% of searches return within three seconds', 'The system should be fast', 'Users should like the system', 'Improve performance when possible'], answer: 0, why: 'It defines a measurable quality and operating condition.' },
  { q: 'What does traceability connect?', choices: ['Objectives, requirements, implementation, tests, results, releases, and documentation', 'Only tickets to users', 'Only vendors to contracts', 'Passwords to administrators'], answer: 0, why: 'Traceability demonstrates purpose, coverage, and change impact.' },
  { q: 'What is UAT primarily intended to establish?', choices: ['Authorized users confirm the solution supports required business outcomes and acceptance criteria', 'Developers prove every line of code is correct', 'The vendor accepts the customer contract', 'Monitoring proves production has no defects'], answer: 0, why: 'User acceptance testing evaluates business fitness.' },
  { q: 'Which regression tests should run first when time is limited?', choices: ['Critical journeys and changed, integrated, security-sensitive, high-impact, and historically fragile areas', 'Only the newest screen', 'Random low-use features', 'Tests that always pass fastest'], answer: 0, why: 'Risk-based selection maximizes useful confidence.' },
  { q: 'What is the difference between defect severity and priority?', choices: ['Severity is impact; priority is the order or urgency of correction', 'Severity is assigned by users and priority by software', 'They are always identical', 'Priority measures reproducibility only'], answer: 0, why: 'A severe defect may have a workaround, and a less severe defect may be urgent for a deadline.' },
  { q: 'What should exist before a risky production configuration change?', choices: ['Approval, current state, test evidence, dependencies, communication, rollback, validation, monitoring, and ownership', 'Only a verbal request', 'A vendor marketing announcement', 'An empty support queue'], answer: 0, why: 'Configuration can have code-like production impact and needs controlled lifecycle management.' },
  { q: 'Which process is the strongest automation candidate?', choices: ['A stable, frequent, rule-based workflow with reliable data and clear ownership', 'A disputed policy with changing exceptions', 'A rare high-risk judgment with no review', 'A process nobody understands'], answer: 0, why: 'Stable rules, volume, data, and ownership make automation more valuable and supportable.' },
  { q: 'What does idempotency mean in workflow automation?', choices: ['Repeating an operation does not create unintended additional effects', 'Every run completes instantly', 'No human can review the flow', 'The flow requires no data'], answer: 0, why: 'Idempotency prevents duplicate side effects during retry or duplicate events.' },
  { q: 'Why should critical flows avoid dependence on one employee’s personal connection?', choices: ['Role changes, departure, licensing, credential changes, or excessive privileges can break or expose the flow', 'Personal connections always run faster', 'Service accounts need no governance', 'Flows cannot access SaaS systems'], answer: 0, why: 'Managed ownership and least-privilege connections reduce continuity and security risk.' },
  { q: 'Which automation measure best reflects business value?', choices: ['Cycle time, error rate, effort, exceptions, compliance, experience, reliability, and operating cost compared with baseline', 'Total run count alone', 'Number of connectors purchased', 'Length of the flow'], answer: 0, why: 'Activity volume alone does not prove a better outcome.' },
  { q: 'What should happen before moving a large file share into SharePoint?', choices: ['Inventory content, owners, permissions, sensitivity, dependencies, volume, disposition, and destination design', 'Copy everything into one library immediately', 'Delete files older than one year automatically', 'Give all users site-owner access'], answer: 0, why: 'Discovery and information architecture determine safe scope and destination.' },
  { q: 'Why test SharePoint permissions with a normal user?', choices: ['Administrator access can hide missing or excessive permissions and navigation problems', 'Normal users can change tenant settings', 'Owners cannot access documents', 'Permission mapping is automatic'], answer: 0, why: 'Validation must represent the actual user experience.' },
  { q: 'What makes a representative migration pilot?', choices: ['It includes varied sizes, many small files, deep paths, permissions, sensitive data, and real dependencies', 'It contains only one easy folder', 'It uses only empty files', 'It excludes business owners'], answer: 0, why: 'Different content patterns reveal different compatibility and performance risks.' },
  { q: 'What can limit SharePoint migration throughput?', choices: ['Source read speed, migration-host disk, network, file distribution, concurrency, timing, and service throttling', 'Only destination storage capacity', 'Only the number of administrators', 'Document colors'], answer: 0, why: 'Migration is an end-to-end pipeline with several shared bottlenecks.' },
  { q: 'Why use bulk followed by incremental migration passes?', choices: ['Move most content early, remediate errors, and reduce final cutover changes and downtime', 'Avoid validating the destination', 'Make source ownership unnecessary', 'Bypass throttling permanently'], answer: 0, why: 'Incremental passes narrow the final delta while preserving controlled cutover.' },
  { q: 'Which migration validation is most complete?', choices: ['Counts, sizes, content samples, permissions, metadata, versions in scope, search, links, automation, integrations, and user acceptance', 'Confirm the destination site opens', 'Count folders only', 'Ask the administrator whether it looks right'], answer: 0, why: 'Successful transfer includes content, access, behavior, dependencies, and outcomes.' },
  { q: 'What should every knowledge article include?', choices: ['Audience, purpose, prerequisites, tested steps, expected result, escalation, owner, and review date', 'Only screenshots', 'An administrator password', 'Every historical version inline'], answer: 0, why: 'These elements make guidance safe, usable, and maintainable.' },
  { q: 'What belongs in a known-issue article?', choices: ['Symptom, scope, cause if known, identifiers, safe workaround, risks, versions, owner, and resolution state', 'Only the workaround', 'Unverified blame', 'Private user data unrelated to diagnosis'], answer: 0, why: 'Known issues must support recognition and safe action without hiding risk or status.' },
  { q: 'What should Tier 1 guidance make clear?', choices: ['Authorized actions, evidence to gather, expected results, stop conditions, and escalation requirements', 'How to bypass permissions', 'How to close every ticket', 'Vendor contract pricing'], answer: 0, why: 'Boundaries and handoff quality protect users and speed escalation.' },
  { q: 'Why normalize ticket categories before trend analysis?', choices: ['Inconsistent labels and duplicate meanings can create false patterns or hide real ones', 'It guarantees root cause automatically', 'It removes the need to sample records', 'It increases ticket count'], answer: 0, why: 'Clean categories and sampled validation make analysis credible.' },
  { q: 'A release causes failures only for one integration. What is the best immediate approach?', choices: ['Limit impact, preserve evidence, compare release and integration changes, use rollback or workaround criteria, and involve the owner and vendor', 'Change every application setting', 'Delete failed records', 'Wait silently for users to adapt'], answer: 0, why: 'Controlled containment and evidence protect the service while isolating the changed dependency.' },
  { q: 'An automated approval sends duplicate purchase orders after retries. Which design concern was missed?', choices: ['Idempotency and duplicate-event handling', 'Screen resolution', 'Document retention only', 'User training only'], answer: 0, why: 'Retries must not repeat high-impact side effects.' }
]

